insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','aceite','Aceite de motor y filtro','Cambiar',20000,12,null,false,'fabricante','Plan Citroën','Programa Citroën del motor NFU: cada 20.000 km o 1 año. En coches con la modificación de febrero de 2009 (OPR 11788) Citroën lo alargó a 30.000 km o 2 años; si no sabes cuál es el tuyo, quédate con 20.000 km.',0);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'fabricante','Plan Citroën','Programa Citroën del motor TU5 (RTA/Haynes): cada 60.000 km. En zonas con polvo, antes.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',20000,12,null,false,'fabricante','Plan Citroën','El plan Citroën del Xsara Picasso lo cambia en cada revisión.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','bujias','Bujías','Cambiar',60000,48,null,false,'fabricante','Plan Citroën','Programa Citroën del motor TU5 (RTA/Haynes): cada 60.000 km.',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','frenos-liquido','Líquido de frenos','Cambiar',null,24,null,false,'fabricante','Plan Citroën','El plan Citroën del Xsara Picasso lo cambia cada 2 años, hagas los km que hagas (dato leído en las versiones gasolina; no depende del motor y los planes PSA de los mismos diésel dicen lo mismo).',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','refrigerante','Líquido refrigerante','Revisar',null,60,null,false,'aproximado','Plazo aproximado','Citroën solo pide comprobar el nivel en cada revisión (líquido de larga duración). Pasados unos 5 años conviene cambiarlo o al menos comprobar su protección; si cambias la bomba de agua con la distribución, se renueva entonces.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','distribucion','Correa de distribución','Cambiar',120000,120,null,false,'fabricante','Plan Citroën','Programa Citroën del motor NFU: 120.000 km o 10 años. Para coches con la modificación de febrero de 2009 (OPR 11788) Citroën pasó a 150.000 km o 10 años; si no lo sabes, cámbiala a los 120.000.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','correa','Correa de accesorios (alternador)','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Revisar grietas y tensión en cada revisión. Lo habitual es cambiarla junto con la distribución.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','filtro-gasolina','Filtro de gasolina','Cambiar',60000,null,null,false,'aproximado','Plazo aproximado','No encontré el plazo Citroën. Va bajo el coche, en el tubo de gasolina; 60.000 km es lo habitual.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','frenos-traseros','Revisar frenos traseros','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','Según versión lleva tambor o disco detrás. Revisar desgaste y freno de mano.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','bateria','Batería: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Caja manual sin cambio de aceite programado: revisar nivel y fugas. Si cuesta meter marchas, cambiarlo.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','revision-bajos','Revisión de bajos y chasis','Revisar',20000,12,null,false,'fabricante','Plan Citroën','La revisión Citroën incluye controles de escape, suspensión, dirección, fuelles de transmisión y tubos de freno.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','embrague','Embrague: revisar','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Comprobar que no patina y el recorrido del pedal. Si patina o huele a quemado, al taller.',16);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-16v-110','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',17);
