insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','filtro-aire','Filtro de aire del motor','Cambiar',60000,48,null,false,'gemelo','Plan Peugeot 1007/407 (gemelo)','En el plan PSA de los HDi la revisión grande de cada 60.000 km incluye el filtro de aire.',1);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','filtro-habitaculo','Filtro de habitáculo (polen)','Cambiar',20000,24,null,false,'gemelo','Plan Peugeot 1007/407 (gemelo)','El plan PSA lo cambia en cada revisión. Si notas olor o poco aire, antes.',2);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','frenos-liquido','Líquido de frenos','Cambiar',null,24,null,false,'fabricante','Plan Citroën','El plan Citroën del Xsara Picasso lo cambia cada 2 años, hagas los km que hagas (dato leído en las versiones gasolina; no depende del motor y los planes PSA de los mismos diésel dicen lo mismo).',3);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','refrigerante','Líquido refrigerante','Revisar',null,60,null,false,'aproximado','Plazo aproximado','Citroën solo pide comprobar el nivel en cada revisión (líquido de larga duración). Pasados unos 5 años conviene cambiarlo o al menos comprobar su protección; si cambias la bomba de agua con la distribución, se renueva entonces.',4);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','distribucion','Correa de distribución','Cambiar',240000,120,null,false,'gemelo','Plan Peugeot 1007/407 (gemelo)','Plan PSA del motor 1.6 HDi (Peugeot 1007 y 407, y el carnet Peugeot citado en foros): 240.000 km o 10 años. Muchos talleres la cambian antes (180.000 km) en uso duro o si el tensor hace ruido. Va con bomba de agua. El dato es del 1.6 HDi 110; este 90 CV lleva el mismo tipo de distribución.',5);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','correa','Correa de accesorios (alternador)','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Revisar grietas y tensión en cada revisión. Lo habitual es cambiarla junto con la distribución.',6);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','filtro-gasoil','Filtro de gasoil','Cambiar',40000,null,null,false,'aproximado','Plazo aproximado','Las fuentes no coinciden: el plan del Peugeot 1007 1.6 HDi lo cambia cada 40.000 km y el del 407 cada 60.000. Ponemos 40.000. Purga el agua en cada cambio de aceite.',7);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','frenos-delanteros','Revisar pastillas y discos delanteros','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Revisar en cada revisión. Cambiar pastillas con menos de 3 mm de material.',8);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','frenos-traseros','Revisar frenos traseros','Revisar',40000,24,null,false,'aproximado','Plazo aproximado','Según versión lleva tambor o disco detrás. Revisar desgaste y freno de mano.',9);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','neumaticos','Neumáticos: rotar y revisar','Revisar',10000,12,null,false,'aproximado','Plazo aproximado','Recomendación general, no del fabricante. Presión una vez al mes. Cambiar con menos de 3 mm de dibujo (mínimo legal 1,6 mm) o con más de 6 años.',10);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','escobillas','Escobillas limpiaparabrisas','Cambiar',null,12,null,false,'aproximado','Plazo aproximado','Cada año o cuando dejen marcas.',11);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','bateria','Batería: comprobar','Revisar',null,12,null,false,'aproximado','Plazo aproximado','Comprobar carga antes del invierno. Suele durar entre 4 y 6 años. En un diésel, una batería floja da arranques difíciles en frío.',12);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','caja-cambios','Aceite de caja de cambios','Revisar',60000,48,null,false,'aproximado','Plazo aproximado','Caja manual sin cambio de aceite programado: revisar nivel y fugas. Si cuesta meter marchas, cambiarlo.',13);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','revision-bajos','Revisión de bajos y chasis','Revisar',20000,24,null,false,'gemelo','Plan Peugeot 1007/407 (gemelo)','La revisión PSA incluye controles de escape, suspensión, dirección, fuelles de transmisión y tubos de freno.',14);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','embrague','Embrague: revisar','Revisar',20000,12,null,false,'aproximado','Plazo aproximado','Comprobar que no patina y el recorrido del pedal. Si patina o huele a quemado, al taller.',15);
insert into maintenance_tasks (model_id,code,name,action,interval_km,interval_months,special,info_only,source_type,source_label,why,sort) values ('citroen-xsara-picasso-n68-16-hdi-90','itv','ITV','Pasar',null,null,'itv',false,'normativa','Normativa ITV','Turismos: primera a los 4 años, después cada 2 años y cada año a partir de los 10 años.',16);
insert into vehicle_models (id,make,model,generation,version,year_from,year_to,engine_code,engine_desc,fuel,power_kw,specs) values ('citroen-xsara-picasso-n68-16-hdi-110-fap','Citroën','Xsara Picasso','N68','1.6 HDi 110 CV FAP',2004,2010,'9HZ (DV6TED4)','Xsara Picasso N68, 2004–2010 · motor 9HZ (DV6TED4) 1560 cc, 109 CV · diésel · con filtro de partículas (FAP) y aditivo Eolys','diesel',80,'[["Motor", "9HZ (DV6TED4), 4 cilindros, 1560 cc, 80 kW (109 CV)"], ["Distribución", "Por correa (motor DV6 HDi), que también mueve la bomba de agua. Cambio con kit completo."], ["Aceite motor", "SAE 5W-30 ACEA C2 low SAPS (PSA B71 2290), obligatorio por el FAP · unos 3,75 L con filtro (cantidad aproximada: comprueba con la varilla)"], ["Neumáticos", "185/65 R15 88H (llanta 5,5 o 6 x 15)"], ["Precalentamiento", "4 bujías de precalentamiento (calentadores), sin cambio programado"], ["Frenos", "Delante disco ventilado. Detrás tambor o disco según versión y año: mira detrás de la rueda antes de comprar."], ["Líquido de frenos", "DOT 4"], ["Caja de cambios", "Manual de 5 marchas"], ["Filtro de partículas", "FAP con aditivo Eolys en depósito propio (Eolys 176 / DPX10 según el catálogo Bosal para el Xsara Picasso)"]]'::jsonb);
